export const OFFICER_TEXT=TRANSLATION_ROWS;
export const OFFICER_LANGUAGES=Object.freeze(['de','en','uk','ja','fr','it','id','ar','ko','sv','pt','nl','th','km','fil']);
export function officerLanguage(documentRef=globalThis.document){
 const current=String(documentRef?.documentElement?.lang||'de').toLowerCase();
 return OFFICER_LANGUAGES.includes(current)?current:'de';
}
export function officerLocale(documentRef=globalThis.document){
 return LOCALES[officerLanguage(documentRef)]||'de-DE';
}
export function translateOfficerText(source,lang='de'){
 if(lang==='de'||!OFFICER_TEXT[lang]||typeof source!=='string')return source;
 const trimmed=source.trim();
 if(!trimmed)return source;
 const translated=OFFICER_TEXT[lang][trimmed];
 if(typeof translated!=='string'||!translated||translated===trimmed)return source;
 const start=source.match(/^\s*/u)?.[0]||'';
 const end=source.match(/\s*$/u)?.[0]||'';
 return start+translated+end;
}
const textNodes=(root)=>root.ownerDocument.createTreeWalker(root,4);
const SKIP_PARENTS=new Set(['SCRIPT','STYLE','TEXTAREA','OPTIONHIDDEN','CODE','PRE']);
function isStaticNode(node){
 const parent=node.parentElement;
 return parent&&!SKIP_PARENTS.has(parent.tagName)&&!parent.closest('[contenteditable="true"],[data-native-no-translate]');
}
export function localizeOfficerTree(root,lang=officerLanguage(root?.ownerDocument)){
 if(!root||lang==='de'||!OFFICER_TEXT[lang])return 0;
 let count=0;
 const walker=textNodes(root),nodes=[];
 while(walker.nextNode())nodes.push(walker.currentNode);
 for(const node of nodes){
  if(!isStaticNode(node))continue;
  const next=translateOfficerText(node.nodeValue,lang);
  if(next!==node.nodeValue){node.nodeValue=next;count++}
 }
 for(const element of root.querySelectorAll('[placeholder],[title],[aria-label],[alt]')){
  if(element.closest('[data-native-no-translate]'))continue;
  for(const field of ['placeholder','title','aria-label','alt']){
   if(!element.hasAttribute(field))continue;
   const before=element.getAttribute(field);
   const after=translateOfficerText(before,lang);
   if(after!==before){element.setAttribute(field,after);count++}
  }
 }
 return count;
}
